DO $$
BEGIN
    IF '${custodian_hash}' LIKE '${%}' OR length(trim('${custodian_hash}')) < 20 THEN
        RAISE EXCEPTION 'CRITICAL SECURITY FAILURE: SOVEREIGN_CUSTODIAN_PASSWORD_HASH is missing or invalid. Aborting migration.';
    END IF;
    IF '${support_hash}' LIKE '${%}' OR length(trim('${support_hash}')) < 20 THEN
        RAISE EXCEPTION 'CRITICAL SECURITY FAILURE: SOVEREIGN_SUPPORT_PASSWORD_HASH is missing or invalid. Aborting migration.';
    END IF;
    IF '${verifier_hash}' LIKE '${%}' OR length(trim('${verifier_hash}')) < 20 THEN
        RAISE EXCEPTION 'CRITICAL SECURITY FAILURE: SOVEREIGN_VERIFIER_PASSWORD_HASH is missing or invalid. Aborting migration.';
    END IF;
    IF '${approver_hash}' LIKE '${%}' OR length(trim('${approver_hash}')) < 20 THEN
        RAISE EXCEPTION 'CRITICAL SECURITY FAILURE: SOVEREIGN_APPROVER_PASSWORD_HASH is missing or invalid. Aborting migration.';
    END IF;
END $$;

UPDATE ${table_prefix}USER 
SET status = 0, nonLocked = false, credentialsNonExpired = false 
WHERE username IN ('admin', 'anonymous');

-- Platform Fleet Governance INSERT INTO ${table_prefix}PERMISSION (uid, code, description, type, level, version) VALUES ('perm-fleet-read', 'platform:fleet:read', 'Inspect fleet inventory and cluster telemetry', 'PLATFORM', 'SYSTEM', 0), ('perm-fleet-mutate', 'platform:fleet:mutate', 'Update platform routing and maintenance flags', 'PLATFORM', 'SYSTEM', 0), ('perm-fleet-circuit', 'platform:fleet:circuit_trip', 'Emergency systemic circuit breaker trip', 'PLATFORM', 'SYSTEM', 0), ('perm-tenant-assume', 'platform:tenant:assume', 'Assume tenant context for support', 'PLATFORM', 'SYSTEM', 0), ('perm-tenant-suspend', 'platform:tenant:suspend', 'Suspend offending tenant access', 'PLATFORM', 'SYSTEM', 0), ('perm-tenant-purge-req', 'platform:tenant:purge:request', 'Request permanent tenant data shredding', 'PLATFORM', 'SYSTEM', 0), ('perm-tenant-purge-app', 'platform:tenant:purge:approve', 'Dual-custody approve tenant data purge', 'PLATFORM', 'SYSTEM', 0), ('perm-quotas-override', 'platform:quotas:override', 'Override tenant quota ceilings', 'PLATFORM', 'SYSTEM', 0), ('perm-roles-manage', 'platform:roles:manage', 'Manage sovereign system roles and DAGs', 'PLATFORM', 'SYSTEM', 0), ('perm-users-lock', 'platform:users:lock', 'Emergency cross-tenant account lockdown', 'PLATFORM', 'SYSTEM', 0) ON CONFLICT (code) DO NOTHING;
