-- Commercial Inside-Tenant Permissions INSERT INTO ${table_prefix}PERMISSION (uid, code, description, type, level, version) VALUES ('perm-org-ws-read', 'org:workspace:read', 'View workspace metadata and provisioned schemas', 'ORGANIZATION', 'TENANT', 0), ('perm-org-ws-mutate', 'org:workspace:mutate', 'Update workspace branding and settings', 'ORGANIZATION', 'TENANT', 0), ('perm-org-mbr-invite', 'org:member:invite', 'Invite team members to workspace', 'ORGANIZATION', 'TENANT', 0), ('perm-org-mbr-manage', 'org:member:manage', 'Manage member statuses and role delegations', 'ORGANIZATION', 'TENANT', 0), ('perm-org-bill-read', 'org:billing:read', 'View subscription usage and invoices', 'ORGANIZATION', 'TENANT', 0), ('perm-org-bill-upg', 'org:billing:upgrade', 'Initiate plan tier upgrades', 'ORGANIZATION', 'TENANT', 0), ('perm-rec-read', 'entity:record:read', 'Read dynamic business entity records', 'ORGANIZATION', 'TENANT', 0), ('perm-rec-create', 'entity:record:create', 'Create dynamic business entity records', 'ORGANIZATION', 'TENANT', 0), ('perm-rec-update', 'entity:record:update', 'Update dynamic business entity records', 'ORGANIZATION', 'TENANT', 0), ('perm-rec-delete', 'entity:record:delete', 'Soft-delete dynamic business entity records', 'ORGANIZATION', 'TENANT', 0), ('perm-org-wf-submit', 'org:workflow:submit', 'Submit record for internal approval', 'ORGANIZATION', 'TENANT', 0), ('perm-org-wf-approve', 'org:workflow:approve', 'Approve internal workflow transition', 'ORGANIZATION', 'TENANT', 0), ('perm-org-audit-read', 'org:audit:read', 'Read tenant record change history deltas', 'ORGANIZATION', 'TENANT', 0) ON CONFLICT (code) DO NOTHING;

-- Map ROOT: All platform, metadata, security, billing, workflow permissions INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-system-root', p.uid FROM ${table_prefix}PERMISSION p WHERE p.type IN ('PLATFORM', 'METADATA', 'SECURITY', 'COMMERCIAL', 'WORKFLOW') ON CONFLICT DO NOTHING;
-- Map SUPPORT: Fleet read, assume tenant, quota override, reconcile billing, feature grants INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-system-support', p.uid FROM ${table_prefix}PERMISSION p WHERE p.code IN ( 'platform:fleet:read', 'platform:tenant:assume', 'platform:quotas:override', 'billing:reconcile', 'tenant:feature:grant', 'metadata:schema:read' ) ON CONFLICT DO NOTHING;
-- Map VERIFIER: Audit verify, security inspect, compliance export, KYC verify, workflow verify INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-system-verifier', p.uid FROM ${table_prefix}PERMISSION p WHERE p.code IN ( 'platform:audit:verify', 'platform:security:inspect', 'platform:compliance:export', 'platform:kyc:verify', 'platform:workflow:verify', 'platform:fleet:read' ) ON CONFLICT DO NOTHING;
-- Map APPROVER: Quorum approve, tenant purge approve, circuit trip, KYC approve INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-system-approver', p.uid FROM ${table_prefix}PERMISSION p WHERE p.code IN ( 'platform:workflow:approve', 'platform:tenant:purge:approve', 'platform:circuit_trip', 'platform:kyc:approve' ) ON CONFLICT DO NOTHING;
-- Map WORKSPACE_OWNER: All org:* and entity:record:* permissions + schema read INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-workspace-owner', p.uid FROM ${table_prefix}PERMISSION p WHERE p.type = 'ORGANIZATION' OR p.code = 'metadata:schema:read' ON CONFLICT DO NOTHING;
-- Map OPERATIONS_MANAGER: Record CRUD, workflow submit/approve, schema read INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-operations-manager', p.uid FROM ${table_prefix}PERMISSION p WHERE p.code IN ( 'entity:record:read', 'entity:record:create', 'entity:record:update', 'entity:record:delete', 'org:workflow:submit', 'org:workflow:approve', 'metadata:schema:read' ) ON CONFLICT DO NOTHING;
-- Map STANDARD_MEMBER: Record read/write, schema read INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-standard-member', p.uid FROM ${table_prefix}PERMISSION p WHERE p.code IN ( 'entity:record:read', 'entity:record:create', 'entity:record:update', 'metadata:schema:read' ) ON CONFLICT DO NOTHING;
-- Map AUDITOR: Record read, org audit read, schema read INSERT INTO ${table_prefix}ROLEPERMISSION (role_uid, permission_uid) SELECT 'role-auditor', p.uid FROM ${table_prefix}PERMISSION p WHERE p.code IN ('entity:record:read', 'org:audit:read', 'metadata:schema:read') ON CONFLICT DO NOTHING;

-- 1. Chief Platform Custodian (Root) INSERT INTO ${table_prefix}USER ( uid, username, email, firstname, lastname, password, nonexpired, nonlocked, credentialsnonexpired, status, type, version, createddate ) VALUES ( 'usr-custodian-root', 'custodian.root', 'custodian@platform.unipost.internal', 'Chief Platform', 'Custodian', '${custodian_hash}', true, true, false, 1, 'SOVEREIGN', 0, CURRENT_TIMESTAMP ) ON CONFLICT (username) DO UPDATE SET password = '${custodian_hash}', credentialsnonexpired = false, nonlocked = true;
-- 2. Customer Operations Lead INSERT INTO ${table_prefix}USER ( uid, username, email, firstname, lastname, password, nonexpired, nonlocked, credentialsnonexpired, status, type, version, createddate ) VALUES ( 'usr-support-ops', 'ops.support', 'support-ops@platform.unipost.internal', 'Customer Operations', 'Lead', '${support_hash}', true, true, false, 1, 'SOVEREIGN', 0, CURRENT_TIMESTAMP ) ON CONFLICT (username) DO UPDATE SET password = '${support_hash}', credentialsnonexpired = false, nonlocked = true;
-- 3. Lead Governance, Audit & KYC Verifier INSERT INTO ${table_prefix}USER ( uid, username, email, firstname, lastname, password, nonexpired, nonlocked, credentialsnonexpired, status, type, version, createddate ) VALUES ( 'usr-system-verifier', 'verifier.system', 'verifier@platform.unipost.internal', 'Platform Governance', 'Verifier', '${verifier_hash}', true, true, false, 1, 'SOVEREIGN', 0, CURRENT_TIMESTAMP ) ON CONFLICT (username) DO UPDATE SET password = '${verifier_hash}', credentialsnonexpired = false, nonlocked = true;
-- 4. Lead Quorum & Governance Approver INSERT INTO ${table_prefix}USER ( uid, username, email, firstname, lastname, password, nonexpired, nonlocked, credentialsnonexpired, status, type, version, createddate ) VALUES ( 'usr-system-approver', 'approver.system', 'approver@platform.unipost.internal', 'Four-Eyes Quorum', 'Approver', '${approver_hash}', true, true, false, 1, 'SOVEREIGN', 0, CURRENT_TIMESTAMP ) ON CONFLICT (username) DO UPDATE SET password = '${approver_hash}', credentialsnonexpired = false, nonlocked = true;
-- Bind personas to roles in USERROLE stamped with tenant_id = 'SYSTEM' INSERT INTO ${table_prefix}USERROLE (user_uid, role_uid, tenant_id) VALUES ('usr-custodian-root', 'role-system-root', 'SYSTEM'), ('usr-support-ops', 'role-system-support', 'SYSTEM'), ('usr-system-verifier', 'role-system-verifier', 'SYSTEM'), ('usr-system-approver', 'role-system-approver', 'SYSTEM') ON CONFLICT DO NOTHING;
